def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        raise ValueError("Archive is empty")

    # Select a nondominated solution with high normalized scores
    objectives = np.array([obj for _, obj in archive])
    pareto_front = []
    for i in range(len(objectives)):
        is_dominated = False
        for j in range(len(objectives)):
            if i != j and (objectives[j][0] >= objectives[i][0] and objectives[j][1] >= objectives[i][1]):
                if objectives[j][0] > objectives[i][0] or objectives[j][1] > objectives[i][1]:
                    is_dominated = True
                    break
        if not is_dominated:
            pareto_front.append(i)

    if not pareto_front:
        pareto_front = list(range(len(archive)))

    scores = []
    for idx in pareto_front:
        sol, (v1, v2) = archive[idx]
        total_weight = np.sum(weight_lst * sol)
        if total_weight > capacity:
            scores.append(0)
        else:
            norm_v1 = v1 / (np.max(value1_lst) + 1e-6)
            norm_v2 = v2 / (np.max(value2_lst) + 1e-6)
            norm_weight = total_weight / (capacity + 1e-6)
            score = (norm_v1 + norm_v2) / (1 + norm_weight)
            scores.append(score)

    if not scores:
        selected_idx = np.random.choice(len(archive))
    else:
        selected_idx = pareto_front[np.argmax(scores)]

    base_solution = archive[selected_idx][0].copy()
    new_solution = base_solution.copy()
    n_items = len(weight_lst)

    # Cluster items by dominance (items that outperform others in both objectives)
    included_indices = np.where(base_solution == 1)[0]
    if len(included_indices) > 0:
        dominance_scores = []
        for i in included_indices:
            v1, v2 = value1_lst[i], value2_lst[i]
            dominated_count = 0
            for j in included_indices:
                if i != j and (value1_lst[j] >= v1 and value2_lst[j] >= v2):
                    if value1_lst[j] > v1 or value2_lst[j] > v2:
                        dominated_count += 1
            dominance_scores.append(dominated_count)

        # Cluster by dominance: high dominance (few dominate) vs. low dominance (many dominate)
        median_dominance = np.median(dominance_scores)
        high_dominance_cluster = included_indices[np.array(dominance_scores) <= median_dominance]
        low_dominance_cluster = included_indices[np.array(dominance_scores) > median_dominance]

        # Probabilistically flip clusters
        if random.random() < 0.5 and len(high_dominance_cluster) > 0:
            flip_cluster = high_dominance_cluster
        else:
            flip_cluster = low_dominance_cluster

        if len(flip_cluster) > 0:
            for i in flip_cluster:
                new_solution[i] = 1 - new_solution[i]

        # Ensure feasibility
        current_weight = np.sum(weight_lst * new_solution)
        if current_weight > capacity:
            # Prioritize removing items with the least dominance (highest dominated_count)
            flip_dominance = np.array([dominance_scores[np.where(included_indices == i)[0][0]] for i in flip_cluster])
            sorted_indices = flip_cluster[np.argsort(flip_dominance)[::-1]]

            for i in sorted_indices:
                if current_weight <= capacity:
                    break
                if new_solution[i] == 1:
                    new_solution[i] = 0
                    current_weight -= weight_lst[i]

        # Guided swaps to maximize marginal Pareto improvements
        if len(high_dominance_cluster) > 0 and len(low_dominance_cluster) > 0:
            # Find best candidate from high_dominance_cluster to remove
            high_dominance_candidates = [i for i in high_dominance_cluster if new_solution[i] == 1]
            if high_dominance_candidates:
                best_high = min(high_dominance_candidates, key=lambda x: dominance_scores[np.where(included_indices == x)[0][0]])

            # Find best candidate from low_dominance_cluster to add
            low_dominance_candidates = [i for i in low_dominance_cluster if new_solution[i] == 0]
            if low_dominance_candidates:
                best_low = max(low_dominance_candidates, key=lambda x: (value1_lst[x] + value2_lst[x]) / (weight_lst[x] + 1e-6))

            if high_dominance_candidates and low_dominance_candidates:
                potential_weight = current_weight - weight_lst[best_high] + weight_lst[best_low]
                if potential_weight <= capacity:
                    new_solution[best_high] = 0
                    new_solution[best_low] = 1

    return new_solution

